WITH pembro_rcc_trials AS (
  SELECT DISTINCT nct_id FROM v_programs WHERE asset_id='pembrolizumab' AND condition_key='D002292'
),
total AS (
  SELECT count(*) AS n, list(nct_id) AS ids FROM pembro_rcc_trials
),
combo AS (
  SELECT count(DISTINCT cp.nct_id) AS n, list(DISTINCT cp.nct_id) AS ids
  FROM v_combo_partners cp
  WHERE cp.asset_id='pembrolizumab' AND cp.condition_key='D002292'
)
SELECT (SELECT n FROM total) AS total_pembro_rcc_trials,
       (SELECT n FROM combo) AS combo_trials;

