WITH prog AS (
  SELECT nct_ids FROM v_programs WHERE asset_id='pembrolizumab' AND condition_key='D002292'
),
total_ids AS (
  SELECT unnest(nct_ids) AS nct_id FROM prog
),
total AS (
  SELECT count(DISTINCT nct_id) AS n FROM total_ids
),
combo AS (
  SELECT count(DISTINCT cp.nct_id) AS n
  FROM v_combo_partners cp
  WHERE cp.asset_id='pembrolizumab' AND cp.condition_key='D002292'
)
SELECT (SELECT n FROM total) AS total_pembro_rcc_trials,
       (SELECT n FROM combo) AS combo_trials;

SELECT count(DISTINCT partner_asset_id) AS n_distinct_partners
FROM v_combo_partners
WHERE asset_id='pembrolizumab' AND condition_key='D002292';

