{"sql": "
WITH prog AS (
  SELECT nct_ids FROM v_programs WHERE asset_id='pembrolizumab' AND condition_key='D002292'
),
total_ids AS (
  SELECT unnest(nct_ids) AS nct_id FROM prog
),
combo_ids AS (
  SELECT DISTINCT cp.nct_id
  FROM v_combo_partners cp
  WHERE cp.asset_id='pembrolizumab' AND cp.condition_key='D002292'
),
mono_ids AS (
  SELECT t.nct_id FROM total_ids t
  LEFT JOIN combo_ids c ON t.nct_id=c.nct_id
  WHERE c.nct_id IS NULL
)
SELECT count(*) AS n_mono_or_unmatched, list(nct_id) AS sample_ids FROM mono_ids;
"}

